// Package keys holds the data-protection keys: the keys that seal rows
// (#139), encrypt fields (#140), and compute blind indexes. Each data key is
// generated by the application and stored in the data_keys table wrapped by
// a key-encryption key (KEK) that stays in a key management service, so the
// database alone never holds a usable key. The keys are unwrapped once at
// startup and kept in memory only.
package keys

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/sha256"
	"errors"
	"fmt"
	"hash"
	"strconv"
)

// Purpose is what a data key is for. Every key has exactly one purpose, and
// Key only offers the operation of its purpose.
type Purpose string

const (
	// PurposeRowMAC seals rows with HMAC-SHA-256.
	PurposeRowMAC Purpose = "row-mac"
	// PurposeFieldEnc encrypts fields with AES-256-GCM.
	PurposeFieldEnc Purpose = "field-enc"
	// PurposeBlindIndex computes HMAC-SHA-256 blind indexes of encrypted
	// values that must be searchable by equality.
	PurposeBlindIndex Purpose = "blind-index"
)

// Purposes lists every purpose, in a fixed order.
var Purposes = []Purpose{PurposeRowMAC, PurposeFieldEnc, PurposeBlindIndex}

// Valid reports whether p is one of Purposes.
func (p Purpose) Valid() bool {
	for _, known := range Purposes {
		if p == known {
			return true
		}
	}
	return false
}

func (p Purpose) isMAC() bool { return p == PurposeRowMAC || p == PurposeBlindIndex }

// KeySize is the size of every data key: 256 bits.
const KeySize = 32

var (
	// ErrNoKey reports a purpose or version that the keyring does not hold.
	ErrNoKey = errors.New("no such data key")
	// ErrWrongPurpose reports an operation that the key's purpose does not
	// allow, such as encrypting with a MAC key.
	ErrWrongPurpose = errors.New("the key's purpose does not allow this operation")
	// ErrBinding reports an unwrapped key that names another purpose or
	// version than its row, for example a wrapped key copied to another row.
	ErrBinding = errors.New("the unwrapped key does not belong to its row")
)

// Key is one version of a data key. Its bytes never leave the type: it
// offers the operation of its purpose, and printing it shows only the
// purpose and the version.
type Key struct {
	purpose Purpose
	version int
	secret  []byte
}

// Purpose returns the purpose of the key.
func (k Key) Purpose() Purpose { return k.purpose }

// Version returns the version of the key, which seals and ciphertexts store
// so that they can be checked or decrypted after a rotation.
func (k Key) Version() int { return k.version }

// String returns the purpose and the version, never the key.
func (k Key) String() string { return fmt.Sprintf("%s/v%d", k.purpose, k.version) }

// GoString hides the key from %#v as well.
func (k Key) GoString() string { return "keys.Key(" + k.String() + ")" }

// NewMAC returns an HMAC-SHA-256 keyed with a row-mac or blind-index key.
func (k Key) NewMAC() (hash.Hash, error) {
	if !k.purpose.isMAC() || len(k.secret) != KeySize {
		return nil, fmt.Errorf("%w: %s cannot compute a MAC", ErrWrongPurpose, k)
	}
	return hmac.New(sha256.New, k.secret), nil
}

// NewAEAD returns AES-256-GCM keyed with a field-enc key.
func (k Key) NewAEAD() (cipher.AEAD, error) {
	if k.purpose != PurposeFieldEnc || len(k.secret) != KeySize {
		return nil, fmt.Errorf("%w: %s cannot encrypt", ErrWrongPurpose, k)
	}
	block, err := aes.NewCipher(k.secret)
	if err != nil {
		return nil, err
	}
	return cipher.NewGCM(block)
}

// bindingTag starts every wrapped plaintext, so that a future format can be
// told apart.
const bindingTag = "crypto-exchange/data-key/1"

// bind returns the plaintext that a provider wraps: the tag, the purpose, and
// the version, each ended by a NUL byte, which none of them contains, and
// then the key. A key unwrapped from another row is therefore refused.
func bind(purpose Purpose, version int, secret []byte) []byte {
	var b bytes.Buffer
	for _, field := range []string{bindingTag, string(purpose), strconv.Itoa(version)} {
		b.WriteString(field)
		b.WriteByte(0)
	}
	b.Write(secret)
	return b.Bytes()
}

// unbind checks that plaintext was bound to purpose and version, and returns
// the key.
func unbind(plaintext []byte, purpose Purpose, version int) ([]byte, error) {
	expected := bind(purpose, version, nil)
	if len(plaintext) != len(expected)+KeySize || !bytes.Equal(plaintext[:len(expected)], expected) {
		return nil, fmt.Errorf("%w: expected %s/v%d", ErrBinding, purpose, version)
	}
	return append([]byte(nil), plaintext[len(expected):]...), nil
}
